from argparse import ArgumentParser
import ute_wtssim.cli.configurator as configurator


def parse_arguments():
    """ Method that parses CLI arguments. """
    parser = ArgumentParser(description="Command line interface for configuring and starting egate.")
    subparsers = parser.add_subparsers(title='subcommands')
    _add_configure_subparser(subparsers)
    _add_start_subparser(subparsers)
    _add_kill_subparser(subparsers)
    args = parser.parse_args()
    args.func(args)


def _add_configure_subparser(subparsers):
    """ Method that parses 'configure' argument to CLI. """
    parser = subparsers.add_parser('configure', help='Configure egate and bring it to either CONFIGURED or ACTIVE state.')
    parser.add_argument('-c', '--cfg_file', help="Path to lua file with egate configuration.", metavar='PATH')
    parser.add_argument('-s', '--suite_file', help="Path to xml file with egate test suite configuration.", metavar='PATH')
    parser.add_argument('-g', '--egate_port', default=20000, help="Specify egate port. Default port number is 20000.", metavar='PORT')
    parser.add_argument('-e', '--edaemon_ports', nargs='+', default=(10000, 30000), metavar='PORT',
                        help="List of ports to start edaemon process. Single value is supported. Default port numbers are 10000 and 30000.")
    parser.add_argument('-d', '--lua_dirs', nargs='*', default=(), metavar='PATH',
                        help="One or more directory paths where lua scripts are stored.")
    parser.add_argument('-r', '--state', default="ACTIVE", choices=['ACTIVE', 'CONFIGURED'],
                        help="Required state of egate (CONFIGURED or ACTIVE)")
    parser.add_argument('-t', '--tool_dir', default=None, help="Path to directory where WTS binaries are available.", metavar='PATH')
    parser.add_argument('-x', '--ext', nargs='*', default=(), help="Extension library or extension class. Single value possible.")
    parser.add_argument('--disable_check_version', dest='check_version', default=True, action='store_false',
                        help="Disable version checking between WTS binaries.")
    parser.add_argument('--retry', default=0, help="Number of retries to start wts services.", metavar='X')
    parser.set_defaults(func=configurator.configure_egate)


def _add_start_subparser(subparsers):
    """ Method that parses 'start' argument to CLI. """
    parser = subparsers.add_parser('start', help='Execute "start" command on CONFIGURED egate and bring it to ACTIVE state.')
    parser.add_argument('-g', '--egate_port', default=20000, help="Specify egate process port. Default port number is 20000.", metavar='PORT')
    parser.add_argument('--disable_check_version', dest='check_version', default=True, action='store_false',
                        help="Disable version checking between WTS binaries.")
    parser.add_argument('--retry', default=0, help="Number of retries to start wts services.", metavar='X')
    parser.set_defaults(func=configurator.start_egate_only)


def _add_kill_subparser(subparsers):
    """ Method that parses 'kill' argument to CLI. """
    parser = subparsers.add_parser('kill', help='Kill running edaemon and/or egate processes.')
    parser.add_argument('-e', '--edaemon', nargs='+', default=(10000, 30000),
                        help="Kill currently running edaemon processes. Default port numbers are 10000 and 30000.", metavar='PORT')
    parser.add_argument('-g', '--egate', default=20000, help="Kill currently running egate process. Default port number is 20000.", metavar='PORT')
    parser.set_defaults(func=configurator.kill_egate_and_edaemon)
